\item[S2] R. Fröberg, S. Lundqvist, A. Oneto and B. Shapiro, \emph{Algebraic Stories from One and from the Other Pockets}, arXiv:1801.01692 (2018), §2, Conjecture 2.2. \url{https://arxiv.org/abs/1801.01692}.
\end{description}
